    entry = _GRAPH_CACHE.get(key)
    if entry is None:
        if len(_GRAPH_CACHE) >= _MAX_GRAPHS:
            # Inputs are being reallocated every call; graph capture would cost
            # more than it saves. Degrade permanently to the eager path.
            _GRAPH_DISABLED = True
            return _affine(x, y)
        try:
            entry = _capture(x, y)
        except Exception:
