            return _affine(x, y)
        _GRAPH_CACHE[key] = entry
    graph, static_out = entry
    try:
        graph.replay()
    except Exception:
        _GRAPH_DISABLED = True
        return _affine(x, y)
    # static_out is reused by every replay, so hand back a fresh tensor.
    return static_out.clone()
