# Optimized implementation path.
#
# The work itself is tiny (8192 fp32 elements), so the measured latency is
# dominated by per-kernel launch overhead rather than by GPU arithmetic.
# Two bounded changes are applied on top of the naive chain:
#
#   1) Fewer, in-place eager kernels.  1.25*x + 0.75*y - 0.125 is rewritten as
#      1.25*(x + 0.6*y) - 0.125, which lets the first step combine both inputs
#      in a single `add(..., alpha=)` kernel, and the remaining steps run as
#      in-place mutations of that freshly allocated result.  The inputs are
#      never written to and the returned tensor is always a fresh allocation.
#
#   2) CUDA graph replay for repeated calls on the same input buffers.  The
#      four launches collapse into a single graph launch.  The cache is keyed
#      on the exact memory the graph reads (data pointers, shapes, strides,
#      dtypes, devices), and every call still returns a `.clone()` of the
#      graph's output buffer so the observable aliasing semantics of the naive
#      implementation are preserved.
#
# Any failure or unsupported situation falls back permanently to the eager
# path, which produces identical values.
# ---------------------------------------------------------------------------

_GRAPH_CACHE = {}
_GRAPH_MAX_ENTRIES = 32
_GRAPH_DISABLED = False


def _affine_eager(x, y):
    out = torch.add(x, y, alpha=0.6)
    out.mul_(1.25)
    out.sub_(0.125)
    return out.clamp_min_(0.0)


def _graph_key(x, y):
    return (
        x.data_ptr(), y.data_ptr(),
        x.shape, y.shape,
        x.stride(), y.stride(),
        x.dtype, y.dtype,
        x.device, y.device,
    )


def _capture(x, y):
    warmup_stream = torch.cuda.Stream()
    warmup_stream.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(warmup_stream):
        for _ in range(3):
