_GRAPH_DISABLED = False
_GRAPH_CACHE = {}
_MAX_GRAPHS = 8


def inputs_for(rows, cols):
    x = (torch.linspace(-2, 2, rows * cols, device='cuda', dtype=torch.float32) + 3).reshape(rows, cols)
    return {'x': x, 'y': x.flip(-1)}

def get_inputs():
    return inputs_for(32, 256)

def get_test_cases():
    return [
        {'name': 'minimal', 'category': 'minimal', 'inputs': inputs_for(1, 1)},
        {'name': 'representative', 'category': 'representative', 'inputs': get_inputs()},
        {'name': 'boundary', 'category': 'boundary', 'inputs': inputs_for(2, 32)},
        {'name': 'ragged', 'category': 'ragged', 'inputs': inputs_for(3, 17)},
    ]

def get_benchmark_inputs():
    return [{'name': 'primary', 'inputs': get_inputs()}, {'name': 'small', 'inputs': inputs_for(2, 32)}]

def reference(inputs):
    return torch.relu(inputs['x'] * 1.25 + inputs['y'] * 0.75 - 0.125)


def _affine(x, y):
    # 1.25*x + 0.75*y - 0.125 == 1.25*(x + 0.6*y) - 0.125, clamped at 0.
    # 4 launches instead of the baseline's 6; all writes land on a fresh
    # out-of-place result (torch.add), so the input tensors are never touched.
    out = torch.add(x, y, alpha=0.6)
    out.mul_(1.25)
    out.sub_(0.125)
    return out.clamp_min_(0.0)


def _capture(x, y):
    graph = torch.cuda.CUDAGraph()
    side = torch.cuda.Stream()
    side.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(side):
        for _ in range(3):
            _affine(x, y)
    torch.cuda.current_stream().wait_stream(side)
    torch.cuda.synchronize()
    with torch.cuda.graph(graph):
        static_out = _affine(x, y)
    return graph, static_out


def run(inputs):
    global _GRAPH_DISABLED
    x = inputs['x']
    y = inputs['y']
    if _GRAPH_DISABLED or not (x.is_cuda and y.is_cuda):
        return _affine(x, y)
    # The graph pins x/y by address, so a replay is only valid for the exact
    # (pointer, shape, stride, dtype, device) tuple it was captured with; the
    # captured kernels read whatever currently lives at those addresses.
    key = (x.data_ptr(), y.data_ptr(), x.shape, x.stride(), y.shape, y.stride(),
